// Dynamic scorecard image (LinkedIn preview + shown on the result page).
// Draws the Strike48 bot from /public/bot.png.
import { ImageResponse } from '@vercel/og';
import React from 'react';
export const config = { runtime: 'edge' };

// Logos + bot embedded directly so the image never depends on a network fetch.
const LOGO_STRIKE = 'data:image/png;base64,';
const BOT_IMG = 'data:image/png;base64,';


export default function handler(req) {
  const url = new URL(req.url);
  const q = url.searchParams;
  // ---- per-event branding -------------------------------------------------
  // Upload the PNGs to /public in the repo. Set a flag to false and the card
  // falls back to text instead of breaking, so it can never 500 at the booth.
  const EVENT_LOGO_ON   = true;                 // needs /public/event-logo.png
  const PARTNER_LOGO_ON = true;                 // needs /public/partner-logo.png
  const EVENT_NAME_TXT  = 'c0c0n 2026';         // text fallback if flag is false
  const PARTNER_TXT     = 'Prudent';            // text fallback if flag is false
  const EVENT_LOGO_URL   = url.origin + '/event-logo.png';
  const PARTNER_LOGO_URL = url.origin + '/partner-logo.png';
  // -------------------------------------------------------------------------
  const name = q.get('n') || 'Analyst';
  const company = q.get('co') || '';
  const id = q.get('id') || '';
  const time = q.get('t') || '0.0';
  const rank = q.get('r') || 'Analyst';
  const correct = q.get('c') || '0';
  const bot = q.get('b') || '3.5';
  const ev = q.get('ev') || '';
  const chall = (q.get('ch') || 'Beat the Bot').toUpperCase();
  const row = (label, color, key) => React.createElement('div', { key, style: { color, fontSize: 32, marginTop: 8, display: 'flex' } }, label);

  return new ImageResponse(
    React.createElement('div', {
      style: {
        width: '100%', height: '100%', display: 'flex', flexDirection: 'column',
        padding: '44px 64px 40px', background: 'linear-gradient(135deg,#0b1730,#070d18)',
        color: '#EAEFF8', fontFamily: 'sans-serif', position: 'relative'
      }
    }, [
      // Header row is IN THE FLOW, so the logos can never overlap the text below.
      React.createElement('div', { key: 'hdr', style: { display: 'flex', width: '100%', alignItems: 'center', justifyContent: 'space-between' } }, [
        EVENT_LOGO_ON
          ? React.createElement('img', { key: 'evlogo', src: EVENT_LOGO_URL, width: 190, height: 56, style: { objectFit: 'contain' } })
          : React.createElement('div', { key: 'evtxt', style: { display: 'flex', color: '#8FA0BD', fontSize: 26, fontWeight: 700 } }, EVENT_NAME_TXT),
        React.createElement('div', { key: 'rt', style: { display: 'flex', alignItems: 'center' } }, [
          React.createElement('img', { key: 's48logo', src: LOGO_STRIKE, width: 180, height: 44 }),
          React.createElement('div', { key: 'x', style: { display: 'flex', color: '#43526f', fontSize: 30, fontWeight: 600, margin: '0 16px' } }, '\u00d7'),
          PARTNER_LOGO_ON
            ? React.createElement('img', { key: 'ptlogo', src: PARTNER_LOGO_URL, width: 247, height: 44, style: { objectFit: 'contain' } })
            : React.createElement('div', { key: 'pttxt', style: { display: 'flex', color: '#EAEFF8', fontSize: 26, fontWeight: 700 } }, PARTNER_TXT)
        ])
      ]),
      React.createElement('div', { key: 'chall', style: { color: '#F5B301', fontSize: 23, letterSpacing: 4, display: 'flex', marginTop: 36 } }, chall + '  \u00b7  AGENTIC SOC CHALLENGE'),
      React.createElement('div', { key: 'head', style: { fontSize: 56, fontWeight: 700, marginTop: 12, display: 'flex' } }, 'I raced the Agentic SOC'),
      React.createElement('div', { key: 'name', style: { fontSize: 84, fontWeight: 700, color: '#F5B301', marginTop: 2, display: 'flex' } }, name),
      company ? React.createElement('div', { key: 'co', style: { fontSize: 28, color: '#8fa0bd', display: 'flex' } }, company) : null,
      id ? row('ID: ' + id, '#8fa0bd', 'id') : null,
      row('Rank: ' + rank, '#c3d0e6', 'r1'),
      row('My time: ' + time + 's  \u00b7  ' + correct + '/3 correct', '#c3d0e6', 'r2'),
      row('The AI triaged in ' + bot + 's', '#3D82F7', 'r3'),
      React.createElement('div', { key: 'sp', style: { display: 'flex', flex: 1 } }),
      React.createElement('div', { key: 'ev', style: { color: '#5b6b88', fontSize: 21, display: 'flex' } }, ev),
      React.createElement('img', { key: 'bot', src: BOT_IMG, width: 280, height: 265, style: { position: 'absolute', right: 60, bottom: 38 } })
    ]),
    { width: 1200, height: 630 }
  );
}
